from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

def test_dependency_scope_function():
    call_count = 0
    def my_dependency():
        nonlocal call_count
        call_count += 1
        yield "value"

    app = FastAPI()
    @app.get("/", dependencies=[Depends(my_dependency, scope="function")])
    def read_root(dep = Depends(my_dependency)):
        return {"hello": "world"}

    client = TestClient(app)
    client.get("/")
    assert call_count == 2

def test_dependency_scope_request():
    call_count = 0
    def my_dependency():
        nonlocal call_count
        call_count += 1
        yield "value"

    app = FastAPI()
    @app.get("/", dependencies=[Depends(my_dependency, scope="request")])
    def read_root(dep = Depends(my_dependency)):
        return {"hello": "world"}

    client = TestClient(app)
    client.get("/")
    assert call_count == 1
